WITH sales_by_item AS ( SELECT i.i_item_sk, i.i_category, i.i_product_name, SUM(ws.ws_net_profit) AS total_profit, SUM(ws.ws_ext_sales_price) AS total_sales, SUM(ws.ws_quantity) AS total_quantity, AVG(ws.ws_sales_price) AS avg_sales_price, MAX(w.w_warehouse_name) AS warehouse_name, MAX(p.wp_type) AS page_type FROM web_sales ws JOIN item i ON ws.ws_item_sk = i.i_item_sk JOIN warehouse w ON ws.ws_warehouse_sk = w.w_warehouse_sk JOIN web_page p ON ws.ws_web_page_sk = p.wp_web_page_sk GROUP BY i.i_item_sk, i.i_category, i.i_product_name ), ranked_items AS ( SELECT *, RANK() OVER (PARTITION BY i_category ORDER BY total_profit DESC) AS profit_rank FROM sales_by_item ) SELECT i_category, i_product_name, total_profit, total_sales, total_quantity, avg_sales_price, warehouse_name, page_type, CASE WHEN total_profit > 100000 THEN 'Very High' WHEN total_profit > 50000 THEN 'High' WHEN total_profit > 10000 THEN 'Medium' ELSE 'Low' END AS profit_category, profit_rank FROM ranked_items WHERE profit_rank <= 5 ORDER BY i_category, profit_rank
